import org.junit.Test;
import static org.junit.Assert.*;
import org.apache.commons.lang.StringUtils;

public class StringUtilsContainsIgnoreCaseTest {

    @Test
    public void testContainsIgnoreCase() {
        // Test cases from Javadoc
        assertFalse(StringUtils.containsIgnoreCase(null, "abc"));
        assertFalse(StringUtils.containsIgnoreCase("abc", null));
        assertTrue(StringUtils.containsIgnoreCase("", ""));
        assertTrue(StringUtils.containsIgnoreCase("abc", ""));
        assertTrue(StringUtils.containsIgnoreCase("abc", "a"));
        assertFalse(StringUtils.containsIgnoreCase("abc", "z"));
        assertTrue(StringUtils.containsIgnoreCase("abc", "A"));
        assertFalse(StringUtils.containsIgnoreCase("abc", "Z"));

        // Additional test cases for case insensitivity
        assertTrue(StringUtils.containsIgnoreCase("HelloWorld", "hello"));
        assertTrue(StringUtils.containsIgnoreCase("HelloWorld", "WORLD"));
        assertTrue(StringUtils.containsIgnoreCase("JavaProgramming", "java"));
        assertTrue(StringUtils.containsIgnoreCase("JavaProgramming", "PROGRAMMING"));
        assertTrue(StringUtils.containsIgnoreCase("aBcDeF", "bCd"));
        assertTrue(StringUtils.containsIgnoreCase("aBcDeF", "BCd"));
        assertTrue(StringUtils.containsIgnoreCase("aBcDeF", "bcD"));

        // Test cases for empty strings
        assertTrue(StringUtils.containsIgnoreCase("test", ""));
        assertTrue(StringUtils.containsIgnoreCase("", ""));
        assertFalse(StringUtils.containsIgnoreCase(null, "")); // As per docstring, null str returns false

        // Test cases where search string is longer than the main string
        assertFalse(StringUtils.containsIgnoreCase("abc", "abcd"));
        assertFalse(StringUtils.containsIgnoreCase("a", "AA"));

        // Test with special characters
        assertTrue(StringUtils.containsIgnoreCase("Hello-World", "-"));
        assertTrue(StringUtils.containsIgnoreCase("Hello_World", "_"));
        assertTrue(StringUtils.containsIgnoreCase("Hello World!", "world!"));
        assertTrue(StringUtils.containsIgnoreCase("Hello World!", "WORLD!"));

        // Test with identical strings, different cases
        assertTrue(StringUtils.containsIgnoreCase("Test", "test"));
        assertTrue(StringUtils.containsIgnoreCase("test", "Test"));
        assertTrue(StringUtils.containsIgnoreCase("TEST", "test"));

        // Test with non-matching strings
        assertFalse(StringUtils.containsIgnoreCase("apple", "orange"));
        assertFalse(StringUtils.containsIgnoreCase("banana", "grape"));
        assertFalse(StringUtils.containsIgnoreCase("one", "two"));
    }
}
